const stdout = $input.first().json.stdout;
let result;

try {
  result = JSON.parse(stdout);
} catch (e) {
  result = { error: 'Failed to parse script output: ' + e.message, removed: [], count: 0 };
}

if (result.error) {
  return [{
    json: {
      count: 1,
      error: result.error,
      discordPayload: {
        embeds: [{
          title: '⚠️ Cross-Seed Cleanup Error',
          description: result.error,
          color: 15158332,
          timestamp: new Date().toISOString(),
          footer: { text: 'Cross-Seed Cleanup Automation' }
        }]
      }
    }
  }];
}

const fields = result.removed.map(t => ({
  name: t.name,
  value: `${t.percentDone}% complete | ${t.ageHours}h old`,
  inline: false
}));

const displayFields = fields.slice(0, 25);

const embed = {
  title: '🧹 Cross-Seed Cleanup',
  description: `Removed **${result.count}** stuck torrent(s)` + (result.torrentFilesCleaned ? ` and cleaned **${result.torrentFilesCleaned}** .torrent file(s)` : ''),
  color: 16744576,
  fields: displayFields,
  timestamp: new Date().toISOString(),
  footer: { text: 'Cross-Seed Cleanup Automation' }
};

return [{
  json: {
    count: result.count,
    removed: result.removed,
    discordPayload: { embeds: [embed] }
  }
}];
